    //      1
    //     / \
    //    2   3
    //   / \
    //  4   5
    Node* root = new_node(1);
    root->left = new_node(2);
    root->right = new_node(3);
    root->left->left = new_node(4);
    root->left->right = new_node(5);
    return root;
}
```

### Explanation
- Manually connects nodes with `->left` and `->right`.
- Produces a 5-node binary tree.

---

## 🔹 Snippet 7: Freeing memory
```c
void free_tree(Node* r) {
    if (!r) return;
    free_tree(r->left);   // free left subtree
    free_tree(r->right);  // free right subtree
    free(r);              // free current node
}
```

### Explanation
- Always free in **postorder** (children before parent).
- Prevents memory leaks.

---

## 🔹 Snippet 8: Main function (driver)
```c
int main(void) {
    Node* root = build_sample_tree();

    printf("Preorder: "); preorder(root); printf("\n");
    printf("Inorder : "); inorder(root);  printf("\n");
    printf("Postorder: "); postorder(root); printf("\n");

    free_tree(root);
    return 0;
}
```

### Expected Output
```
Preorder: 1 2 4 5 3
Inorder : 4 2 5 1 3
Postorder: 4 5 2 3 1
```

